BEGIN;
SET LOCAL search_path='';
SET LOCAL lock_timeout='2s';

DO $velo_r3_pre$
#variable_conflict error
DECLARE

 rr mission_factory_owner.editor_release_readiness%ROWTYPE;
 review jsonb;


 prior_release mission_public_owner.release_admissions_v1%ROWTYPE;
 prior_qualification mission_public_owner.public_qualification_attestations_v1%ROWTYPE;
 generic_ezbr constant text:='9a6889802cfa17c99a556538cccd4ad7ef75274d32adccbc192c23d257aa3e76';

BEGIN

 IF current_user<>'postgres' OR session_user<>'postgres' OR auth.uid() IS NOT NULL
 OR (SELECT rolbypassrls FROM pg_roles WHERE rolname='postgres') IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'VELO_R3_OPERATOR_REQUIRED';
 END IF;
 review:=$velo_r3_review$__VELO_R3_FORWARD_REVIEW_JSON__$velo_r3_review$::jsonb;
 IF NOT mission_factory_owner.keys_exact_v2(review,ARRAY['ref','sha256','P0','P1','P2'])
 OR coalesce(review->>'ref','') !~ '^[A-Za-z0-9_.#-]{1,40}$'
 OR coalesce(review->>'sha256','') !~ '^[a-f0-9]{64}$'
 OR review->'P0' IS DISTINCT FROM '0'::jsonb OR review->'P1' IS DISTINCT FROM '0'::jsonb
 OR review->'P2' IS DISTINCT FROM '0'::jsonb THEN
  RAISE EXCEPTION 'VELO_R3_INDEPENDENT_REVIEW_REQUIRED';
 END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0)) THEN
  RAISE EXCEPTION 'VELO_R3_AVAILABILITY_BUSY';
 END IF;
 SELECT * INTO STRICT rr FROM mission_factory_owner.editor_release_readiness WHERE singleton FOR UPDATE NOWAIT;
 LOCK TABLE public.master_v2_sessions,public.combat_v2_sessions,combat_consumer_private.invitations IN SHARE MODE NOWAIT;
 LOCK TABLE mission_public_owner.release_admissions_v1,mission_public_owner.public_qualification_attestations_v1,
  mission_public_owner.engine_profile_events_v1,mission_public_owner.mission_content_admissions_v1,
  mission_public_owner.party_launch_runtime_v1 IN SHARE ROW EXCLUSIVE MODE NOWAIT;

 IF rr.revision_sha256 IS DISTINCT FROM '2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42'
 OR rr.observed_revision_sha256 IS DISTINCT FROM rr.revision_sha256
 OR encode(extensions.digest(convert_to(rr.canonical_preimage,'UTF8'),'sha256'),'hex') IS DISTINCT FROM rr.revision_sha256
 OR octet_length(rr.canonical_preimage) IS DISTINCT FROM 523908
 OR public.combat_v2_sha256(to_jsonb(rr)) IS DISTINCT FROM '18b00a3a2957c19d8646d8968d770b99bc6b64f89bce866d4906974b76ac549e'
 OR rr.state IS DISTINCT FROM 'enabled' OR rr.scope IS DISTINCT FROM 'staff'
 OR rr.staff_guards_verified IS DISTINCT FROM true OR rr.published_assets_verified IS DISTINCT FROM true
 OR public.combat_v2_sha256(to_jsonb(rr)-ARRAY['canonical_preimage','revision_sha256','observed_revision_sha256',
     'client_build','independent_review_ref','updated_at']) IS DISTINCT FROM '85efdb471dc5560963e027a19649f6dfab701125ca948c0c3d1aa4dce7d6da37'
 OR rr.canonical_preimage::jsonb#>>'{db_core,velo_staff}' IS DISTINCT FROM 'c3612c94016774b3457ea72312e9a1ef763caca10bcec2151a7a522980d13c13'
 OR (SELECT staff_enabled FROM clan_innata_combat_private.velo_staff_gate_v1 WHERE singleton) IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'VELO_R3_EXACT_BASELINE_DRIFT';
 END IF;
 IF EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE closed_at IS NULL AND state IN ('preparazione','in_corso','sospeso'))
 OR EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE closed_at IS NULL AND stato NOT IN ('chiusa','annullata'))
 OR EXISTS(SELECT 1 FROM combat_consumer_private.invitations WHERE state='pending'
    AND location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b')
 OR EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state
   WHERE technique_id='c9b261da-c9cd-40bb-8189-7b65ab5a1605' AND (active OR is_test IS DISTINCT FROM true))
 THEN RAISE EXCEPTION 'VELO_R3_REQUIRES_NO_OPEN_CONTEXT'; END IF;
 PERFORM set_config('app.velo_r3_review',review::text,true);
 PERFORM set_config('app.velo_r3_root_row_sha',public.combat_v2_sha256(to_jsonb(rr)),true);


 IF EXISTS(SELECT 1 FROM jsonb_to_recordset($velo_r3_functions$[{"sig":"clan_innata_combat_private.velo_staff_scope_v1(uuid)","oid":"701892","src":"58bcea50c7964b4357fd15b51364e322","sha":"3b542e31bfbbe18cb167d1532ed565ba18cbb193737f4415e7437d517f769a74","abi":"f818fd9bbd5078095876c503b3a8f82d8ca8de94d6e9e32a4646e0df5dd7c216"},{"sig":"clan_innata_private.catalogo_eligibility_release_v1()","oid":"684829","src":"9c17aacce8e7e38597cd0980d6ed533e","sha":"fa28712daea087bf2611f6d3167aa34576c04b0e598e084501a3033bcbdace27","abi":"7d2dcd85f468271ee5b86ca4cb359d8c8e0adcb8a08af8784f52c7d01ebdec5b"},{"sig":"clan_innata_private.eligibility_release_assert()","oid":"41419","src":"318083236b37a6573e00f7061e41588e","sha":"a195b9b8d0d0a353eaa7c17a9a092223a6cc642b64163cbcf09475312b08dbb1","abi":"7a319aa51034184281d8449c40422632bd7ad214b9f1ad005ba1b390511361ca"}]$velo_r3_functions$::jsonb) e(sig text,oid text,src text,sha text,abi text)
 LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.sig) LEFT JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid::text IS DISTINCT FROM e.oid OR md5(p.prosrc) IS DISTINCT FROM e.src
 OR encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex') IS DISTINCT FROM e.sha
 OR public.combat_v2_sha256(jsonb_build_object('oid',p.oid::text,'owner',pg_get_userbyid(p.proowner),
 'acl',p.proacl::text,'config',p.proconfig,'security_definer',p.prosecdef,'strict',p.proisstrict,
 'volatile',p.provolatile::text,'parallel',p.proparallel::text,'kind',p.prokind::text,'language',l.lanname,
 'returns',pg_get_function_result(p.oid),'arg_types',p.proargtypes::text,'arg_names',p.proargnames,
 'arg_modes',p.proargmodes,'leakproof',p.proleakproof)) IS DISTINCT FROM e.abi)
 THEN RAISE EXCEPTION 'VELO_R3_BEFORE_FUNCTION_ABI_OR_BODY_DRIFT'; END IF;

 PERFORM clan_innata_private.runtime_release_assert();

 SELECT * INTO STRICT prior_release FROM mission_public_owner.release_admissions_v1 WHERE release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42' FOR SHARE;
 SELECT * INTO STRICT prior_qualification FROM mission_public_owner.public_qualification_attestations_v1 WHERE release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42' FOR SHARE;
 IF prior_release.edge_sha256 IS DISTINCT FROM generic_ezbr
 OR public.combat_v2_sha256(to_jsonb(prior_release)) IS DISTINCT FROM '06b2fcf741a2a0b06d57099d34f297450c91968710c9d3e1878f33430b160306'
 OR public.combat_v2_sha256(to_jsonb(prior_qualification)) IS DISTINCT FROM 'f78b851d11160d94e5f250a58160f89577cc67e89c956575d73f4631ab6ad6fd'
 OR public.combat_v2_sha256(prior_qualification.payload->'capabilities') IS DISTINCT FROM '49fe134f561273f28e8071b63c45886341371b67d028f06e6b7d8f8d4108e817'
 OR (SELECT count(*) FROM mission_public_owner.mission_content_admissions_v1 c WHERE c.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42') IS DISTINCT FROM 2::bigint
 OR (SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(c) ORDER BY c.mission_id,c.request_key))
       FROM mission_public_owner.mission_content_admissions_v1 c WHERE c.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42')
   IS DISTINCT FROM 'fdc597562ce70c1c83b3cf99da807c00266fe7ead29742056ab9e77bc570b41f'
 OR (SELECT count(DISTINCT e.profile_key) FROM mission_public_owner.engine_profile_events_v1 e WHERE e.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42') IS DISTINCT FROM 1::bigint
 OR (SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(e) ORDER BY e.profile_key))
       FROM (SELECT DISTINCT ON(z.profile_key) * FROM mission_public_owner.engine_profile_events_v1 z
           WHERE z.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42' ORDER BY z.profile_key,z.control_version DESC) e)
   IS DISTINCT FROM 'ab9dcf7b9216ff62776139ffec6a878b41b1351a11bff63b15470eb831421cbf' THEN
  RAISE EXCEPTION 'VELO_R3_EXISTING_MISSION_EVIDENCE_DRIFT';
 END IF;


 IF mission_public_owner.engine_qualification_v1('2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42',true) IS NULL
  OR (SELECT count(*) FROM mission_public_owner.mission_content_admissions_v1 c
    WHERE c.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42'
      AND mission_public_owner.content_admission_v1(c.mission_id,'2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42',c.publication_request,true) IS NOT NULL)
   IS DISTINCT FROM 2::bigint THEN RAISE EXCEPTION 'VELO_R3_RETAINED_MISSIONS_NOT_QUALIFIED'; END IF;

 IF (SELECT to_jsonb(x) FROM mission_public_owner.party_launch_runtime_v1 x WHERE x.singleton)
 IS DISTINCT FROM $velo_r3_party${"singleton":true,"staff_enabled":true,"public_enabled":true,"release_sha256":"2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42"}$velo_r3_party$::jsonb
 THEN RAISE EXCEPTION 'VELO_R3_PARTY_BASELINE_DRIFT'; END IF;
 PERFORM set_config('app.velo_r3_history',(jsonb_build_array(
 (SELECT count(*) FROM clan_innata_combat_private.velo_staff_profiles_v1),
 (SELECT count(*) FROM clan_innata_combat_private.velo_rapid_turn_receipts_v1),
 (SELECT count(*) FROM clan_innata_combat_private.velo_declaration_stats_v1),
 (SELECT count(*) FROM clan_innata_combat_private.combat_receipts
   WHERE technique_id='c9b261da-c9cd-40bb-8189-7b65ab5a1605')))::text,true);
END
