DO $velo_r3_post$
#variable_conflict error
DECLARE

 rr mission_factory_owner.editor_release_readiness%ROWTYPE;
 review jsonb;


 prior_release mission_public_owner.release_admissions_v1%ROWTYPE;
 prior_qualification mission_public_owner.public_qualification_attestations_v1%ROWTYPE;
 generic_ezbr constant text:='9a6889802cfa17c99a556538cccd4ad7ef75274d32adccbc192c23d257aa3e76';

 namespace_uuid constant uuid:='9ebf5297-66c5-5a19-b35a-589b626e4a4f';
 old_root_sha constant text:='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42';
 new_root_sha constant text:='4aec6254673c4c076d313660659a11a0f0b502d434def8bd7a6e4a5c8776f479';
 db_sha constant text:='46f6d487a0b63906516c699dfb2071286ca0bdf06d96111f672c500d18e44a07';
 config_sha constant text:='a303b9061ab22139e595a5c4b44a977d51bc3037739cfa500eae12d53f5dcece';
 root_text text:=current_setting('app.velo_r3_root_candidate');
 root jsonb;
 params jsonb; content_row mission_public_owner.mission_content_admissions_v1%ROWTYPE;
 runtime_before jsonb; bindings jsonb; qualification jsonb; content_payload jsonb;
 profile_row record; content_request uuid; affected integer;
BEGIN
 review:=current_setting('app.velo_r3_review')::jsonb;
 params:=$velo_r3_p${"expected_mission_capabilities_sha256":"49fe134f561273f28e8071b63c45886341371b67d028f06e6b7d8f8d4108e817","compatibility":{"ref":"velo-staff-ordinary-mission-compat-r3","sha256":"35d754465f1c19509822e9728ade3e23c3d2aefe63f441aff01908e774dfcef6"}}$velo_r3_p$::jsonb;
 root:=root_text::jsonb;

 IF EXISTS(SELECT 1 FROM jsonb_to_recordset($velo_r3_functions$[{"sig":"clan_innata_combat_private.velo_staff_scope_v1(uuid)","oid":"701892","src":"3bb31269a7662aaf16169f76bccd6348","sha":"419382199472a3b3af19a8c04ec0b450b040b7680d8cb864ba03ec5da9a55d67","abi":"f818fd9bbd5078095876c503b3a8f82d8ca8de94d6e9e32a4646e0df5dd7c216"},{"sig":"clan_innata_private.catalogo_eligibility_release_v1()","oid":"684829","src":"37778b193d749fe058330b67d53831c0","sha":"aa75acfc73af99e779b3be25d1969eb7d9251290140760606b8b020e70a94c2f","abi":"7d2dcd85f468271ee5b86ca4cb359d8c8e0adcb8a08af8784f52c7d01ebdec5b"},{"sig":"clan_innata_private.eligibility_release_assert()","oid":"41419","src":"d12a616a859cd2b497004d0f17395437","sha":"d034de670fcf5ad17d3f4663fe209cda5ca3d85e1c8b86f1bff26fb938f002bb","abi":"7a319aa51034184281d8449c40422632bd7ad214b9f1ad005ba1b390511361ca"}]$velo_r3_functions$::jsonb) e(sig text,oid text,src text,sha text,abi text)
 LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.sig) LEFT JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid::text IS DISTINCT FROM e.oid OR md5(p.prosrc) IS DISTINCT FROM e.src
 OR encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex') IS DISTINCT FROM e.sha
 OR public.combat_v2_sha256(jsonb_build_object('oid',p.oid::text,'owner',pg_get_userbyid(p.proowner),
 'acl',p.proacl::text,'config',p.proconfig,'security_definer',p.prosecdef,'strict',p.proisstrict,
 'volatile',p.provolatile::text,'parallel',p.proparallel::text,'kind',p.prokind::text,'language',l.lanname,
 'returns',pg_get_function_result(p.oid),'arg_types',p.proargtypes::text,'arg_names',p.proargnames,
 'arg_modes',p.proargmodes,'leakproof',p.proleakproof)) IS DISTINCT FROM e.abi)
 THEN RAISE EXCEPTION 'VELO_R3_AFTER_FUNCTION_ABI_OR_BODY_DRIFT'; END IF;


 SELECT * INTO STRICT prior_release FROM mission_public_owner.release_admissions_v1 WHERE release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42' FOR SHARE;
 SELECT * INTO STRICT prior_qualification FROM mission_public_owner.public_qualification_attestations_v1 WHERE release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42' FOR SHARE;
 IF prior_release.edge_sha256 IS DISTINCT FROM generic_ezbr
 OR public.combat_v2_sha256(to_jsonb(prior_release)) IS DISTINCT FROM '06b2fcf741a2a0b06d57099d34f297450c91968710c9d3e1878f33430b160306'
 OR public.combat_v2_sha256(to_jsonb(prior_qualification)) IS DISTINCT FROM 'f78b851d11160d94e5f250a58160f89577cc67e89c956575d73f4631ab6ad6fd'
 OR public.combat_v2_sha256(prior_qualification.payload->'capabilities') IS DISTINCT FROM '49fe134f561273f28e8071b63c45886341371b67d028f06e6b7d8f8d4108e817'
 OR (SELECT count(*) FROM mission_public_owner.mission_content_admissions_v1 c WHERE c.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42') IS DISTINCT FROM 2::bigint
 OR (SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(c) ORDER BY c.mission_id,c.request_key))
       FROM mission_public_owner.mission_content_admissions_v1 c WHERE c.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42')
   IS DISTINCT FROM 'fdc597562ce70c1c83b3cf99da807c00266fe7ead29742056ab9e77bc570b41f'
 OR (SELECT count(DISTINCT e.profile_key) FROM mission_public_owner.engine_profile_events_v1 e WHERE e.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42') IS DISTINCT FROM 1::bigint
 OR (SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(e) ORDER BY e.profile_key))
       FROM (SELECT DISTINCT ON(z.profile_key) * FROM mission_public_owner.engine_profile_events_v1 z
           WHERE z.engine_release_sha256='2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42' ORDER BY z.profile_key,z.control_version DESC) e)
   IS DISTINCT FROM 'ab9dcf7b9216ff62776139ffec6a878b41b1351a11bff63b15470eb831421cbf' THEN
  RAISE EXCEPTION 'VELO_R3_EXISTING_MISSION_EVIDENCE_DRIFT';
 END IF;

 SELECT to_jsonb(x) INTO STRICT runtime_before FROM mission_public_owner.party_launch_runtime_v1 x WHERE x.singleton FOR UPDATE;
 IF runtime_before IS DISTINCT FROM $velo_r3_party${"singleton":true,"staff_enabled":true,"public_enabled":true,"release_sha256":"2bcaf1943d787202406fad30d0a628869df77aae792eaa38d089dea41f393e42"}$velo_r3_party$::jsonb THEN RAISE EXCEPTION 'VELO_R3_PARTY_RUNTIME_DRIFT'; END IF;
 bindings:=jsonb_build_object('db_sha256',db_sha,'edge_sha256',generic_ezbr,
  'client_sha256',public.combat_v2_sha256(root->'ui'),'configuration_sha256',config_sha);
 UPDATE mission_factory_owner.editor_release_readiness
 SET canonical_preimage=root_text,revision_sha256=new_root_sha,observed_revision_sha256=new_root_sha,
  client_build='mission-factory-admin/2:'||new_root_sha,independent_review_ref=review->>'ref',updated_at=clock_timestamp()
 WHERE singleton AND revision_sha256=old_root_sha
  AND public.combat_v2_sha256(to_jsonb(editor_release_readiness))=current_setting('app.velo_r3_root_row_sha');
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected<>1 THEN RAISE EXCEPTION 'VELO_R3_ROOT_CAS'; END IF;
 IF NOT clan_innata_private.catalogo_eligibility_release_v1() THEN RAISE EXCEPTION 'VELO_R3_E52_NOT_ATTESTED'; END IF;
 PERFORM clan_innata_private.runtime_release_assert();
 INSERT INTO mission_public_owner.release_admissions_v1(release_sha256,db_sha256,edge_sha256,client_sha256,configuration_sha256,
  contract_version,independent_review_ref,staff_evidence_ref,qualified_at,public_enabled)
 VALUES(new_root_sha,db_sha,generic_ezbr,bindings->>'client_sha256',config_sha,prior_release.contract_version,
  review->>'ref',prior_release.staff_evidence_ref,prior_release.qualified_at,prior_release.public_enabled);
 FOR profile_row IN SELECT DISTINCT ON(profile_key)* FROM mission_public_owner.engine_profile_events_v1
  WHERE engine_release_sha256=old_root_sha ORDER BY profile_key,control_version DESC LOOP
  IF profile_row.profile_key IS DISTINCT FROM prior_qualification.payload->>'authoring_profile' THEN
   RAISE EXCEPTION 'VELO_R3_UNQUALIFIED_PROFILE_CARRYFORWARD';END IF;
  INSERT INTO mission_public_owner.engine_profile_events_v1(event_id,engine_release_sha256,profile_key,expected_control_version,
   control_version,authoring_enabled,runtime_enabled,actor_user,reason)
  VALUES(extensions.uuid_generate_v5(namespace_uuid,new_root_sha||':profile:'||profile_row.profile_key),new_root_sha,profile_row.profile_key,
   0,1,profile_row.authoring_enabled,profile_row.runtime_enabled,profile_row.actor_user,
   'Compatible carryforward of existing mission profile only; new catalog techniques have no Staff PASS');
 END LOOP;
 qualification:=prior_qualification.payload||jsonb_build_object('revision_sha256',new_root_sha,'bindings',bindings,'independent_review',review,
  'reuse_evidence',(prior_qualification.payload->'reuse_evidence')||jsonb_build_object('new_mission_QA_claim',false,
   'catalogo_compatibility',jsonb_build_object('parent_root',old_root_sha,'ref',params#>'{compatibility,ref}',
    'sha256',params#>'{compatibility,sha256}','scope','existing_mission_capabilities_only','new_techniques_staff_pass',false)));
 INSERT INTO mission_public_owner.public_qualification_attestations_v1(release_sha256,request_key,payload,payload_sha256,
  positive_staff_evidence_ref,authorized_test_manifest_ref,created_by)
 VALUES(new_root_sha,extensions.uuid_generate_v5(namespace_uuid,new_root_sha||':qualification'),qualification,mission_factory_owner.sha(qualification),
  prior_qualification.positive_staff_evidence_ref,prior_qualification.authorized_test_manifest_ref,prior_qualification.created_by);
 IF qualification->'capabilities' IS DISTINCT FROM prior_qualification.payload->'capabilities'
 OR public.combat_v2_sha256(qualification->'capabilities') IS DISTINCT FROM params->>'expected_mission_capabilities_sha256'
 OR mission_public_owner.engine_qualification_v1(new_root_sha,true)IS NULL THEN RAISE EXCEPTION 'VELO_R3_MISSION_CARRYFORWARD_INVALID';END IF;
 FOR content_row IN SELECT * FROM mission_public_owner.mission_content_admissions_v1 WHERE engine_release_sha256=old_root_sha ORDER BY mission_id LOOP
  content_request:=extensions.uuid_generate_v5(content_row.request_key,new_root_sha||':catalogo-compatible-adoption');
  content_payload:=content_row.payload||jsonb_build_object('request_key',content_request,'engine_release_sha256',new_root_sha,'created_at',clock_timestamp());
  INSERT INTO mission_public_owner.mission_content_admissions_v1(request_key,mission_id,config_version,engine_release_sha256,publication_request,payload,payload_sha256)
  VALUES(content_request,content_row.mission_id,content_row.config_version,new_root_sha,content_row.publication_request,content_payload,mission_factory_owner.sha(content_payload));
  IF mission_public_owner.content_admission_v1(content_row.mission_id,new_root_sha,content_row.publication_request,true)IS NULL THEN
   RAISE EXCEPTION 'VELO_R3_CONTENT_CARRYFORWARD_INVALID';END IF;
 END LOOP;
 UPDATE mission_public_owner.party_launch_runtime_v1 x SET release_sha256=new_root_sha WHERE singleton AND to_jsonb(x)=runtime_before;
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'VELO_R3_PARTY_RUNTIME_CAS';END IF;


 IF mission_public_owner.engine_qualification_v1('4aec6254673c4c076d313660659a11a0f0b502d434def8bd7a6e4a5c8776f479',true) IS NULL
  OR (SELECT count(*) FROM mission_public_owner.mission_content_admissions_v1 c
    WHERE c.engine_release_sha256='4aec6254673c4c076d313660659a11a0f0b502d434def8bd7a6e4a5c8776f479'
      AND mission_public_owner.content_admission_v1(c.mission_id,'4aec6254673c4c076d313660659a11a0f0b502d434def8bd7a6e4a5c8776f479',c.publication_request,true) IS NOT NULL)
   IS DISTINCT FROM 2::bigint THEN RAISE EXCEPTION 'VELO_R3_RETAINED_MISSIONS_NOT_QUALIFIED'; END IF;

 IF (SELECT to_jsonb(x) FROM mission_public_owner.party_launch_runtime_v1 x WHERE x.singleton)
    IS DISTINCT FROM $velo_r3_party${"singleton":true,"staff_enabled":true,"public_enabled":true,"release_sha256":"4aec6254673c4c076d313660659a11a0f0b502d434def8bd7a6e4a5c8776f479"}$velo_r3_party$::jsonb
 OR current_setting('app.velo_r3_history')::jsonb IS DISTINCT FROM (jsonb_build_array(
 (SELECT count(*) FROM clan_innata_combat_private.velo_staff_profiles_v1),
 (SELECT count(*) FROM clan_innata_combat_private.velo_rapid_turn_receipts_v1),
 (SELECT count(*) FROM clan_innata_combat_private.velo_declaration_stats_v1),
 (SELECT count(*) FROM clan_innata_combat_private.combat_receipts
   WHERE technique_id='c9b261da-c9cd-40bb-8189-7b65ab5a1605')))
 OR (SELECT staff_enabled FROM clan_innata_combat_private.velo_staff_gate_v1 WHERE singleton) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'VELO_R3_POSTFLIGHT_STATE_DRIFT'; END IF;
 PERFORM set_config('app.velo_r3_result',jsonb_build_object('root_sha256',new_root_sha,'root_bytes',octet_length(root_text),
  'previous_root_sha256',old_root_sha,'staff_enabled',true,'ordinary_scope_corrected',true,
  'public_opening',false,'existing_mission_contents',2,'provider_calls',0)::text,true);
END
$velo_r3_post$;

SELECT current_setting('app.velo_r3_result',true)::jsonb AS release_receipt;
COMMIT;
